fn main() {
    let mut m = Matrix::from_elem(2, 3, 0_i32);
    m.set(0, 0, 10);
    m.set(0, 1, 7);
    m.set(0, 2, 30);
    m.set(1, 0, 3);
    m.set(1, 1, 8);
    m.set(1, 2, 5);

    let row1_sum: i32 = m.row(1).unwrap().iter().copied().sum();

